9	/**
10	 * Rejects a create-owner request that is missing or blank in any mandatory field, before the body is
11	 * mapped to an entity. Reads the request published by {@link NormalizeAddress}, so the {@code address}
12	 * has already been normalized: a blank-after-normalization address is rejected here.
13	 */
14	public class RequireOwnerFields {
15	
16	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
17	        List<String> missing = new ArrayList<>();
18	        if (isBlank(request.getFirstName())) {
19	            missing.add("firstName");
20	        }
21	        if (isBlank(request.getLastName())) {
22	            missing.add("lastName");
23	        }
24	        if (isBlank(request.getAddress())) {
25	            missing.add("address");
26	        }
27	        if (isBlank(request.getCity())) {
28	            missing.add("city");
29	        }
30	        if (isBlank(request.getTelephone())) {
31	            missing.add("telephone");
32	        }
33	        if (!missing.isEmpty()) {
34	            throw new MissingOwnerFieldsException(missing);
35	        }
36	    }
37	
38	    private static boolean isBlank(String value) {
39	        return value == null || value.isBlank();
40	    }
41	}
