1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create-owner request whose E.164 telephone is already used by any other owner. Runs after
10	 * {@link NormalizeTelephone} (so the request telephone is already in E.164 form) and before the owner
11	 * is built and saved. Each existing owner's telephone is normalized to E.164 the same way before
12	 * comparison, so numbers stored in any format are matched by their E.164 value. A collision is rejected
13	 * via {@link DuplicateTelephoneException}, which the global handler turns into a 409.
14	 */
15	public class RejectDuplicateTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = request.getTelephone();
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(TelephoneE164.normalizeOrNull(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(request.getTelephone());
23	            }
24	        }
25	    }
26	}
