1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Rejects a create-owner request whose last name and address both match an existing owner, treating
12	 * two households as the same when their last names are equal after trimming, collapsing runs of
13	 * whitespace to a single space, and lower-casing, and their addresses are equal in the normalized form
14	 * ({@link AddressNormalizer}). Runs before the owner is built and saved. The rejection is skipped when
15	 * the request sets {@code sharesHousehold} true, allowing several owners to share one household. A
16	 * collision is rejected via {@link DuplicateHouseholdException}, which the global handler turns into a
17	 * 409.
18	 */
19	public class RejectDuplicateHousehold {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateHouseholdException {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String lastName = normalize(request.getLastName());
27	        String address = AddressNormalizer.normalize(request.getAddress());
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (lastName.equals(normalize(existing.getLastName()))
30	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
31	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
32	            }
33	        }
34	    }
35	
36	    private static String normalize(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
