5	
6	/**
7	 * Business-day helper for owner registration. The effective registration date must fall on a
8	 * business day: when it lands on a Saturday or Sunday it is rolled forward to the next Monday.
9	 * Applies to the effective registration date whether supplied in the request or defaulted to the
10	 * server date, and every value derived from that date (membership-number year, daily create-limit)
11	 * must use the adjusted date.
12	 */
13	final class BusinessDay {
14	
15	    private BusinessDay() {
16	    }
17	
18	    /** Roll a weekend date forward to the next Monday; a business day is returned unchanged. */
19	    static LocalDate adjust(LocalDate date) {
20	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
21	            date = date.plusDays(1);
22	        }
23	        return date;
24	    }
25	}
