15	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
16	
17	    static final String UNKNOWN = "UNKNOWN";
18	
19	    private Locality() {
20	    }
21	
22	    public static String of(String city) {
23	        return CITY_REGION.getOrDefault(city, UNKNOWN);
24	    }
25	}
