10	/**
11	 * Rejects a create-owner request whose lower-cased email is already used by any other owner. Runs after
12	 * {@link NormalizeEmail} (so the request email is already lower-cased) and before the owner is built and
13	 * saved. Email is optional, so an absent or blank value is skipped. Each existing owner's email is
14	 * lower-cased the same way before comparison, so addresses stored in any case are matched by their
15	 * lower-cased value. A collision is rejected via {@link DuplicateEmailException}, which the global
16	 * handler turns into a 409.
17	 */
18	public class RejectDuplicateEmail {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateEmailException {
22	        String email = request.getEmail();
23	        if (email == null || email.isBlank()) {
24	            return;
25	        }
26	        for (Owner existing : ownerRepository.findAll()) {
27	            String existingEmail = existing.getEmail();
28	            if (existingEmail != null && email.equals(existingEmail.trim().toLowerCase(Locale.ROOT))) {
29	                throw new DuplicateEmailException(request.getEmail());
30	            }
31	        }
32	    }
33	}
